import{_ as a,b as t,c as i,l as s}from"./chunks/framework.Czrd0uqa.js";const p=JSON.parse(`{"title":"How It's Made","description":"A quick meta blog on how I developed this site.","frontmatter":{"title":"How It's Made","description":"A quick meta blog on how I developed this site.","longDescription":"Everyone who can, should make a personal website. So here's how I made mine.","date":"1026-2-4"},"headers":[],"relativePath":"blogs/made/index.md","filePath":"blogs/made/index.md"}`),o={name:"blogs/made/index.md"};function d(r,e,n,l,h,m){return t(),i("div",null,[...e[0]||(e[0]=[s('<h2 id="why" tabindex="-1">Why? <a class="header-anchor" href="#why" aria-label="Permalink to “Why?”">​</a></h2><p>I&#39;ve had a personal website since 10th grade. I always wanted to have a personal space to showcase what I work on, however I personally hate website development, so my sites have always been scuffed and buggy. But then, my friend <a href="https://www.outercloud.dev/" target="_blank" rel="noreferrer">Liam Hanrahan</a> built his own website, and it looked really good. So naturally, I had to improve mine.</p><div style="height:20px;"></div><h2 id="what-did-i-use" tabindex="-1">What Did I Use? <a class="header-anchor" href="#what-did-i-use" aria-label="Permalink to “What Did I Use?”">​</a></h2><p>This website is directly forked from Liam Hanrahan&#39;s website, with a few improvements of my own. I primarily do hardware and low-level software. Web dev is far from my favorite task, so naturally, I asked his permission and based my website off of his. Initially I decided to use AI for styling and some widgets. Eventually, though I realized that I&#39;d rather style it myself even if I personally hate CSS with a burning passion. Admittedly, some parts are still by AI due to it touching most files, but the website is gradually becoming more me.</p><div style="height:20px;"></div><div style="height:60px;"></div>',7)])])}const c=a(o,[["render",d]]);export{p as __pageData,c as default};
